const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const seen = new Set(), pts = [];
for (let i = 0; i < n; i++) {
  const x = tok[1 + 2 * i], y = tok[2 + 2 * i], key = x + "," + y;
  if (!seen.has(key)) { seen.add(key); pts.push([x, y]); }
}
pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
let hull;
if (pts.length <= 2) hull = pts;
else {
  const lower = [];
  for (const p of pts) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) lower.pop();
    lower.push(p);
  }
  const upper = [];
  for (let i = pts.length - 1; i >= 0; i--) {
    const p = pts[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) upper.pop();
    upper.push(p);
  }
  hull = lower.slice(0, -1).concat(upper.slice(0, -1));
}
let area2 = 0;
if (hull.length >= 3) {
  for (let i = 0; i < hull.length; i++) {
    const a = hull[i], b = hull[(i + 1) % hull.length];
    area2 += a[0] * b[1] - b[0] * a[1];
  }
}
console.log(hull.length + " " + Math.abs(area2));

