import java.io.*;
import java.util.*;

public class Main {
    static long cross(long[] o, long[] a, long[] b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        long[][] all = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); all[i][0] = (long) in.nval;
            in.nextToken(); all[i][1] = (long) in.nval;
        }
        Arrays.sort(all, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        List<long[]> pts = new ArrayList<>();
        for (long[] p : all) if (pts.isEmpty() || pts.get(pts.size() - 1)[0] != p[0] || pts.get(pts.size() - 1)[1] != p[1]) pts.add(p);
        int m = pts.size();
        List<long[]> hull = new ArrayList<>();
        if (m <= 2) hull.addAll(pts);
        else {
            long[][] st = new long[2 * m + 2][];
            int k = 0;
            for (int i = 0; i < m; i++) {
                while (k >= 2 && cross(st[k - 2], st[k - 1], pts.get(i)) <= 0) k--;
                st[k++] = pts.get(i);
            }
            int lowerSize = k + 1;
            for (int i = m - 2; i >= 0; i--) {
                while (k >= lowerSize && cross(st[k - 2], st[k - 1], pts.get(i)) <= 0) k--;
                st[k++] = pts.get(i);
            }
            for (int i = 0; i < k - 1; i++) hull.add(st[i]);
        }
        long area2 = 0;
        int h = hull.size();
        if (h >= 3)
            for (int i = 0; i < h; i++) {
                long[] a = hull.get(i), b = hull.get((i + 1) % h);
                area2 += a[0] * b[1] - b[0] * a[1];
            }
        System.out.println(h + " " + Math.abs(area2));
    }
}

