#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
ll cross(const P& o, const P& a, const P& b) { return (a.first - o.first) * (b.second - o.second) - (a.second - o.second) * (b.first - o.first); }

int main() {
    int n;
    scanf("%d", &n);
    vector<P> pts(n);
    for (auto& p : pts) scanf("%lld %lld", &p.first, &p.second);
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    int m = pts.size();
    vector<P> hull;
    if (m <= 2) hull = pts;
    else {
        vector<P> st(2 * m + 2);
        int k = 0;
        for (int i = 0; i < m; i++) {
            while (k >= 2 && cross(st[k - 2], st[k - 1], pts[i]) <= 0) k--;
            st[k++] = pts[i];
        }
        for (int i = m - 2, lowerSize = k + 1; i >= 0; i--) {
            while (k >= lowerSize && cross(st[k - 2], st[k - 1], pts[i]) <= 0) k--;
            st[k++] = pts[i];
        }
        hull.assign(st.begin(), st.begin() + k - 1);
    }
    ll area2 = 0;
    int h = hull.size();
    if (h >= 3)
        for (int i = 0; i < h; i++) area2 += hull[i].first * hull[(i + 1) % h].second - hull[(i + 1) % h].first * hull[i].second;
    printf("%d %lld\n", h, llabs(area2));
    return 0;
}
